public interface ICacheService
{
    Task<T?> GetAsync<T>(string key, CancellationToken ct = default);
    Task SetAsync<T>(string key, T value, TimeSpan? ttl = null, CancellationToken ct = default);
    Task RemoveAsync(string key, CancellationToken ct = default);
    Task RemoveByPatternAsync(string pattern, CancellationToken ct = default);
}

public sealed class RedisCacheService(IConnectionMultiplexer multiplexer) : ICacheService, IDisposable
{
    private readonly IDatabase _db = multiplexer.GetDatabase();
    private readonly IServer _server = multiplexer.GetServer(multiplexer.GetEndPoints()[0]);

    public async Task<T?> GetAsync<T>(string key, CancellationToken ct = default)
    {
        var value = await _db.StringGetAsync(key);
        if (!value.HasValue) return default;
        return JsonSerializer.Deserialize<T>(value);
    }

    public async Task SetAsync<T>(string key, T value, TimeSpan? ttl = null, CancellationToken ct = default)
    {
        var json = JsonSerializer.Serialize(value);
        await _db.StringSetAsync(key, json, ttl ?? TimeSpan.FromMinutes(10));
    }

    public async Task RemoveAsync(string key, CancellationToken ct = default)
        => await _db.KeyDeleteAsync(key);

    public async Task RemoveByPatternAsync(string pattern, CancellationToken ct = default)
    {
        var keys = _server.Keys(pattern: pattern).ToArray();
        if (keys.Length > 0)
            await _db.KeyDeleteAsync(keys);
    }

    public void Dispose() => multiplexer.Dispose();
}

public class CachedPolicyQuery(IPolicyRepository repo, ICacheService cache, IOptions<CacheOptions> opts)
    : IPolicyQuery
{
    private readonly string _version = opts.Value.PolicyVersion; // "v3"
    private readonly TimeSpan _ttl = TimeSpan.FromMinutes(30);

    public async Task<IReadOnlyList<PolicyRule>> GetActiveRulesAsync(Guid orgId, CancellationToken ct)
    {
        var key = $"ExpensePlatform:policy:{_version}:{orgId}";
        var cached = await cache.GetAsync<IReadOnlyList<PolicyRule>>(key, ct);
        if (cached is not null) return cached;

        var rules = await repo.GetActiveByOrganizationAsync(orgId, ct);
        await cache.SetAsync(key, rules, _ttl, ct);
        return rules;
    }

    public async Task InvalidateAsync(Guid orgId, CancellationToken ct)
    {
        var pattern = $"ExpensePlatform:policy:*:{orgId}";
        await cache.RemoveByPatternAsync(pattern, ct);
    }
}

public record PolicyRulesChanged(Guid OrganizationId) : INotification;

public class InvalidatePolicyCacheHandler(ICacheService cache, ILogger<InvalidatePolicyCacheHandler> log)
    : INotificationHandler<PolicyRulesChanged>
{
    public async Task Handle(PolicyRulesChanged notification, CancellationToken ct)
    {
        log.LogInformation("Invalidating policy cache for org {OrgId}", notification.OrganizationId);
        await new CachedPolicyQuery(null!, cache, null!).InvalidateAsync(notification.OrganizationId, ct);
    }
}

