{
    var rule = await _policyRepo.GetByIdAsync(request.Id, ct);
    rule.Update(request.MaxAmount, request.RequiresReceipt);
    await _policyRepo.UpdateAsync(rule, ct);
    await _uow.SaveChangesAsync(ct);
    await _mediator.Publish(new PolicyRulesChanged(request.OrganizationId), ct);
    return Result<Unit>.Success(Unit.Value);
