export function usePolicyRules(organizationId: string) {
  return useQuery({
    queryKey: ['policy-rules', organizationId],
    queryKeyHash: ['policy-rules', organizationId].join('-'),
    queryFn: () => fetchPolicyRules(organizationId),
    staleTime: 5 * 60 * 1000, // 5 minutes — policies rarely change
    gcTime: 30 * 60 * 1000,   // 30 minutes in memory after unused
  });
}

